mapper.select:
select p.id,up.nickname,up.avatar,p.rating,p.content,p.images,p.sku_specs,p.create_time
from product_review p
left join user_profile up on p.user_id = up.user_id
left join merchant_profile mp on p.user_id = mp.user_id

    and deleted = 0

    and up.user_id = #{pageQueryBO.userId}


        and mp.user_id = #{pageQueryBO.merchantId}


    and p.product_id = #{pageQueryBO.productId}


    and p.rating = #{pageQueryBO.rating}


order by create_time desc
